<?php get_header(); while ( have_posts() ) : the_post(); $id = get_the_ID(); $terms = get_the_terms( $id, 'igp_category' ); $term = ! is_wp_error( $terms ) && $terms ? $terms[0] : null; $image = igp_product_image( $id ); ?>
<div class="page shell"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="<?php echo esc_url( home_url( '/' ) ); ?>">Home</a><span>/</span><?php if ( $term ) : ?><a href="<?php echo esc_url( get_term_link( $term ) ); ?>"><?php echo esc_html( $term->name ); ?></a><span>/</span><?php endif; ?><span><?php the_title(); ?></span></nav><article class="product-detail"><div class="product-detail-image"><?php if ( $image ) : ?><img src="<?php echo esc_url( $image ); ?>" alt="<?php echo esc_attr( get_the_title() . ' generator part' ); ?>"><?php endif; ?></div><div><p class="eyebrow"><?php echo esc_html( $term ? $term->name : '' ); ?></p><h1><?php the_title(); ?></h1><p class="product-lead"><?php echo esc_html( get_the_excerpt() ); ?></p><dl class="product-facts"><?php foreach ( array( 'working_principle' => 'Working principle', 'daily_use' => 'Daily use', 'manufacturer' => 'Manufacturer', 'part_number' => 'Part number', 'oem_reference'=>'OEM reference','engine_family'=>'Engine family','compatible_brands'=>'Compatible brands','compatible_models'=>'Compatible models' ) as $field => $label ) : $value = get_post_meta( $id, '_igp_' . $field, true ); if ( $value ) : ?><div><dt><?php echo esc_html( $label ); ?></dt><dd><?php echo esc_html( $value ); ?></dd></div><?php endif; endforeach; ?></dl><div class="button-row"><a href="<?php echo esc_url( add_query_arg( 'product', get_post_field( 'post_name', $id ), igp_url( 'request-quote/' ) ) ); ?>" class="button button-primary">Request a quote <span aria-hidden="true">↗</span></a><a class="button button-outline whatsapp-button" target="_blank" rel="noopener noreferrer" href="<?php echo esc_url( igp_whatsapp( get_the_title(), get_permalink() ) ); ?>"><?php echo igp_icon(); ?> Ask on WhatsApp</a></div><?php the_content(); ?></div></article><?php if ( $term ) : $related = new WP_Query( array( 'post_type' => 'igp_product', 'posts_per_page' => 4, 'post__not_in' => array( $id ), 'tax_query' => array( array( 'taxonomy' => 'igp_category', 'field' => 'term_id', 'terms' => $term->term_id ) ) ) ); if ( $related->have_posts() ) : ?><section class="related section"><div class="section-heading"><div><p class="eyebrow">Related components</p><h2>Explore this system.</h2></div><a class="text-link" href="<?php echo esc_url( get_term_link( $term ) ); ?>">View <?php echo esc_html( $term->name ); ?> <span>→</span></a></div><div class="product-grid"><?php while ( $related->have_posts() ) : $related->the_post(); get_template_part( 'template-parts/product', 'card' ); endwhile; ?></div></section><?php endif; wp_reset_postdata(); endif; ?></div><?php endwhile; get_footer(); ?>
